FILES = json.loads('{"main.py": "\\"\\"\\"\\nProject entry point.\\n\\n    python main.py generate --sims 2000 --frames 30     # build the dataset\\n    python main.py train --epochs 100                   # train the MLP\\n    python main.py compare --wind 6 --stiffness 0.5 --damping 0.2\\n    python main.py demo                                 # launch the Streamlit app\\n    python main.py all                                  # generate + train + compare\\n\\nExtra flags after `generate` / `train` are passed straight to those scripts.\\n\\"\\"\\"\\nimport argparse, os, subprocess, sys\\n\\nROOT = os.path.dirname(os.path.abspath(__file__))\\nos.chdir(ROOT)\\nsys.path.insert(0, ROOT)\\n\\n\\ndef run(module, extra):\\n    cmd = [sys.executable, \\"-m\\", module, *extra]\\n    print(\\"\\\\n>>\\", \\" \\".join(cmd))\\n    subprocess.run(cmd, check=True)\\n\\n\\ndef compare(args):\\n    import matplotlib\\n    matplotlib.use(\\"Agg\\")\\n    import numpy as np\\n    from model.predict import ClothPredictor\\n    from visualization import visualize as viz\\n\\n    predictor = ClothPredictor(args.checkpoint)\\n    grid = viz.grid_size(predictor.V)\\n    phys, phys_ms = viz.run_physics(args.wind, args.stiffness, args.damping, args.frames, grid=grid)\\n    mlp, mlp_ms = viz.run_mlp(predictor, args.wind, args.stiffness, args.damping, args.frames)\\n    err = viz.vertex_errors(phys, mlp)\\n\\n    os.makedirs(\\"results\\", exist_ok=True)\\n    shown = sorted({0, args.frames // 3, 2 * args.frames // 3, args.frames})\\n    viz.compare_frames(phys, mlp, predictor.rest, shown).savefig(\\"results/compare_frames.png\\", dpi=130)\\n    gif = viz.animate_compare(phys, mlp, predictor.rest, \\"results/compare.gif\\")\\n\\n    print(f\\"\\\\nwind={args.wind} stiffness={args.stiffness} damping={args.damping} frames={args.frames}\\")\\n    print(f\\"MSE (all coordinates)      : {np.mean((phys - mlp) ** 2):.6f}\\")\\n    print(f\\"mean vertex error, final   : {err[-1] * 100:.2f} cm\\")\\n    print(f\\"physics  (measured)        : {phys_ms:.3f} ms/frame\\")\\n    print(f\\"MLP      (measured)        : {mlp_ms:.3f} ms/frame\\")\\n    print(f\\"speed ratio physics/MLP    : {phys_ms / mlp_ms:.2f}x\\")\\n    print(f\\"saved results/compare_frames.png and {gif}\\")\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)\\n    ap.add_argument(\\"command\\", choices=[\\"generate\\", \\"train\\", \\"compare\\", \\"demo\\", \\"all\\"])\\n    ap.add_argument(\\"--wind\\", type=float, default=6.0)\\n    ap.add_argument(\\"--stiffness\\", type=float, default=0.5)\\n    ap.add_argument(\\"--damping\\", type=float, default=0.2)\\n    ap.add_argument(\\"--frames\\", type=int, default=30)\\n    ap.add_argument(\\"--checkpoint\\", default=\\"model/cloth_mlp.pt\\")\\n    args, extra = ap.parse_known_args()\\n\\n    gen_args = [*extra, \\"--frames\\", str(args.frames)]   # --frames is shared with `compare`\\n    if args.command == \\"generate\\":\\n        run(\\"simulation.generate_dataset\\", gen_args)\\n    elif args.command == \\"train\\":\\n        run(\\"model.train\\", extra)\\n    elif args.command == \\"compare\\":\\n        compare(args)\\n    elif args.command == \\"demo\\":\\n        subprocess.run([sys.executable, \\"-m\\", \\"streamlit\\", \\"run\\", \\"visualization/app.py\\"], check=True)\\n    elif args.command == \\"all\\":\\n        run(\\"simulation.generate_dataset\\", gen_args)   # `all` forwards extra flags to the generator only\\n        run(\\"model.train\\", [])\\n        compare(args)\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n", "README.md": "# Data-Driven Cloth for Interactive Applications\\n\\nA small machine-learning project that trains a neural network (MLP) to imitate a\\nmass-spring cloth simulator. Instead of running the physics every frame, the network\\npredicts the **next cloth frame** from the current state and the physical parameters\\n(wind, stiffness, damping, gravity).\\n\\n```\\nphysics simulator \\u2500\\u2500\\u25ba random simulations \\u2500\\u2500\\u25ba dataset \\u2500\\u2500\\u25ba MLP training \\u2500\\u2500\\u25ba interactive demo\\n```\\n\\n## Project structure\\n\\n```\\ndata-driven-cloth/\\n\\u251c\\u2500\\u2500 simulation/\\n\\u2502   \\u251c\\u2500\\u2500 cloth.py               # mass-spring cloth (NumPy, vectorised)\\n\\u2502   \\u2514\\u2500\\u2500 generate_dataset.py    # runs randomised simulations -> data/*.npz\\n\\u251c\\u2500\\u2500 model/\\n\\u2502   \\u251c\\u2500\\u2500 model.py               # ClothMLP\\n\\u2502   \\u251c\\u2500\\u2500 train.py               # training + evaluation (metrics.json, plots)\\n\\u2502   \\u2514\\u2500\\u2500 predict.py             # ClothPredictor: load checkpoint, roll out frames\\n\\u251c\\u2500\\u2500 visualization/\\n\\u2502   \\u251c\\u2500\\u2500 visualize.py           # plotting / comparison helpers\\n\\u2502   \\u2514\\u2500\\u2500 app.py                 # Streamlit interactive demo\\n\\u251c\\u2500\\u2500 notebooks/\\n\\u2502   \\u2514\\u2500\\u2500 visualization.ipynb    # dataset exploration + results analysis\\n\\u251c\\u2500\\u2500 data/                      # generated datasets (git-ignored)\\n\\u251c\\u2500\\u2500 results/                   # metrics.json, plots, GIFs\\n\\u251c\\u2500\\u2500 main.py                    # single entry point\\n\\u251c\\u2500\\u2500 requirements.txt\\n\\u2514\\u2500\\u2500 README.md\\n```\\n\\n## Setup\\n\\nPython 3.10+ is recommended.\\n\\n```bash\\npython -m venv .venv\\nsource .venv/bin/activate          # Windows: .venv\\\\Scripts\\\\activate\\npip install -r requirements.txt\\n```\\n\\n## Quick start\\n\\n```bash\\npython main.py all                 # generate data -> train -> compare physics vs MLP\\npython main.py demo                # interactive Streamlit app\\n```\\n\\nOr step by step:\\n\\n```bash\\npython main.py generate --sims 2000 --frames 30      # 1. dataset  (data/train|val|test.npz)\\npython main.py train --epochs 100                    # 2. train     (model/cloth_mlp.pt, results/)\\npython main.py compare --wind 6 --stiffness 0.5 --damping 0.2   # 3. GIF + PNG + timings\\npython main.py demo                                  # 4. sliders in the browser\\njupyter notebook notebooks/visualization.ipynb       # 5. analysis notebook\\n```\\n\\nNotes on `main.py`: extra flags after `generate` / `train` are forwarded to those scripts\\n(`--grid`, `--seed`, `--hidden`, `--noise`, `--lr`, ...). `all` forwards extra flags to the\\ndata generator only, so use the separate commands for custom training settings.\\nYou can also call the modules directly, e.g. `python -m model.train --help`.\\n\\n## How it works\\n\\n### 1. Physics simulator (`simulation/cloth.py`)\\n- Cloth = `n x n` grid of particles (default 10 x 10 = 100 vertices) hanging in the x-y plane, top row pinned.\\n- Structural, shear and bend springs using Hooke\'s law, `F = -k (x - L)`.\\n- Forces: gravity + springs + wind + viscous damping. Wind pushes harder on surfaces that face it.\\n- Semi-implicit Euler integration with 5 small sub-steps per frame for stability.\\n\\n### 2. Dataset (`simulation/generate_dataset.py`)\\n- Each simulation samples `wind in [0, 10]`, `stiffness in [0.1, 1.0]`, `damping in [0.01, 0.5]` (gravity fixed at 9.8).\\n- Records positions and velocities for every frame, starting from the rest pose.\\n- Split **by simulation** (80 / 10 / 10) so no trajectory leaks between train and test.\\n- Stored as compressed `.npz`: `positions (S, T+1, V, 3)`, `velocities (S, T+1, V, 3)`, `params (S, 4)`.\\n\\n### 3. Model (`model/`)\\n- Task: **next-frame prediction**.\\n  - input  = `[position - rest, velocity, wind, stiffness, damping, gravity]`\\n  - output = `[delta position, delta velocity]`\\n- MLP `input -> 256 -> 512 -> 512 -> output`, ReLU, MSE loss, AdamW + cosine learning-rate schedule.\\n- Inputs/outputs are standardised with statistics from the training set only.\\n- Pinned vertices are held fixed at prediction time.\\n\\n### 4. Evaluation (`model/train.py` -> `results/metrics.json`)\\n| Metric | Meaning |\\n|---|---|\\n| one-step MSE / MAE | predict frame t+1 from the *true* frame t |\\n| rollout MSE / MAE | start at rest, feed predictions back in for all frames |\\n| per-frame vertex error | mean Euclidean error (metres) over the rollout, vs. a \\"cloth never moves\\" baseline |\\n| error by wind bin | accuracy for weak vs. strong wind |\\n| ms / frame, ratio | measured physics vs. MLP time on your machine |\\n\\nRollout error is the metric that matters for an interactive application, because\\nsmall per-step errors accumulate over time.\\n\\n## Suggested experiments (for the report)\\n\\n1. **Wind strength**: read `rollout_error_by_wind_m` in `results/metrics.json`.\\n2. **Training-set size**: `python main.py generate --sims 1000` / `5000` / `10000`, retrain each, compare errors.\\n3. **Physics vs. ML**: `python main.py compare` for accuracy, visual similarity (GIF) and measured speed.\\n4. **Grid size**: `python main.py generate --grid 32` then retrain. A 10 x 10 cloth is cheap to simulate directly;\\n   the speed comparison becomes more meaningful on larger cloths.\\n5. **Rollout stability**: retrain with `--noise 0.02` and compare the rollout curves.\\n\\n## Results (fill in from your own runs)\\n\\n| Experiment | Setting | One-step MAE | Rollout MAE | Final-frame error (cm) |\\n|---|---|---|---|---|\\n| Training size | 1,000 sims | | | |\\n| Training size | 5,000 sims | | | |\\n| Training size | 10,000 sims | | | |\\n\\n| | ms / frame |\\n|---|---|\\n| Physics (measured) | |\\n| MLP (measured) | |\\n\\nReport only numbers you measured: timings depend on your hardware, grid size and batch size.\\n\\n## Troubleshooting\\n\\n- `ModuleNotFoundError: simulation` / `model`: run commands from the project root (the folder containing `main.py`).\\n- `No trained model found` in the demo: run `python main.py train` first.\\n- Demo/GIF shows an inconsistent cloth: the checkpoint and the physics grid must match; retrain after changing `--grid`.\\n- Rollout drifts or explodes late in the trajectory: more training data, a larger network, or `--noise 0.02`.\\n- Inputs outside the training ranges (wind > 10, etc.) are extrapolation; expect poor predictions.\\n\\n## Limitations\\n\\n- Simplified mass-spring model: no collisions, no self-collision, no tearing.\\n- Fixed grid size and fixed pinning pattern per trained model.\\n- An MLP over all vertices does not scale gracefully to large meshes; graph neural networks are the natural next step.\\n", "requirements.txt": "numpy>=1.24\\ntorch>=2.0\\nmatplotlib>=3.7\\nstreamlit>=1.30\\npandas>=2.0\\njupyter\\nipywidgets>=8.0\\npillow>=10.0\\n", ".gitignore": "__pycache__/\\n*.pyc\\n.ipynb_checkpoints/\\ndata/*.npz\\ndata/*.npy\\nresults/*.gif\\n.venv/\\n", "simulation/__init__.py": "", "simulation/cloth.py": "\\"\\"\\"\\nMass-spring cloth simulator (vectorised NumPy).\\n\\nThe cloth is an n x n grid of particles hanging in the x-y plane, pinned along\\nits top row. Three spring types are used:\\n  - structural : horizontal / vertical neighbours\\n  - shear      : diagonal neighbours\\n  - bend       : neighbours two cells apart (resists folding)\\n\\nForces: gravity + springs (Hooke\'s law) + wind + velocity damping.\\nIntegration: semi-implicit (symplectic) Euler with small sub-steps for stability.\\n\\"\\"\\"\\nimport numpy as np\\n\\nK_SCALE = 400.0  # maps the 0.1-1.0 \\"stiffness\\" knob to a real spring constant\\n\\n\\nclass Cloth:\\n    def __init__(self, n=10, spacing=0.1, mass=0.1, pin=\\"top_row\\"):\\n        self.n = n\\n        self.spacing = spacing\\n        self.mass = mass\\n        self.num_vertices = n * n\\n\\n        # Rest positions: cloth lies in the x-y plane, row 0 at the top\\n        xs, ys = np.meshgrid(np.arange(n) * spacing, -np.arange(n) * spacing)\\n        self.rest_pos = np.stack([xs, ys, np.zeros_like(xs)], axis=-1).reshape(-1, 3)\\n\\n        self.pinned = np.zeros(self.num_vertices, dtype=bool)\\n        if pin == \\"top_row\\":\\n            self.pinned[:n] = True\\n        elif pin == \\"top_corners\\":\\n            self.pinned[[0, n - 1]] = True\\n\\n        self._build_springs()\\n        self.reset()\\n\\n    # ---------------------------------------------------------------- setup\\n    def _build_springs(self):\\n        n = self.n\\n        idx = np.arange(n * n).reshape(n, n)\\n        pairs = []\\n        # structural\\n        pairs += list(zip(idx[:, :-1].ravel(), idx[:, 1:].ravel()))\\n        pairs += list(zip(idx[:-1, :].ravel(), idx[1:, :].ravel()))\\n        # shear\\n        pairs += list(zip(idx[:-1, :-1].ravel(), idx[1:, 1:].ravel()))\\n        pairs += list(zip(idx[:-1, 1:].ravel(), idx[1:, :-1].ravel()))\\n        # bend\\n        pairs += list(zip(idx[:, :-2].ravel(), idx[:, 2:].ravel()))\\n        pairs += list(zip(idx[:-2, :].ravel(), idx[2:, :].ravel()))\\n\\n        pairs = np.array(pairs)\\n        self.sp_i, self.sp_j = pairs[:, 0], pairs[:, 1]\\n        self.sp_rest = np.linalg.norm(\\n            self.rest_pos[self.sp_i] - self.rest_pos[self.sp_j], axis=1\\n        )\\n\\n    def reset(self):\\n        self.pos = self.rest_pos.copy()\\n        self.vel = np.zeros_like(self.pos)\\n\\n    # --------------------------------------------------------------- forces\\n    def _normals(self, pos):\\n        g = pos.reshape(self.n, self.n, 3)\\n        du = np.gradient(g, axis=1)\\n        dv = np.gradient(g, axis=0)\\n        nrm = np.cross(du, dv).reshape(-1, 3)\\n        return nrm / (np.linalg.norm(nrm, axis=1, keepdims=True) + 1e-9)\\n\\n    def _forces(self, stiffness, wind, gravity, wind_dir):\\n        k = stiffness * K_SCALE\\n        f = np.zeros_like(self.pos)\\n\\n        # Gravity\\n        f[:, 1] -= self.mass * gravity\\n\\n        # Springs (Hooke\'s law: F = -k (|d| - L) * d/|d|)\\n        d = self.pos[self.sp_j] - self.pos[self.sp_i]\\n        length = np.linalg.norm(d, axis=1, keepdims=True) + 1e-9\\n        fs = k * (length - self.sp_rest[:, None]) * d / length\\n        np.add.at(f, self.sp_i, fs)\\n        np.add.at(f, self.sp_j, -fs)\\n\\n        # Wind: pushes harder when the cloth surface faces the wind\\n        nrm = self._normals(self.pos)\\n        facing = nrm @ wind_dir\\n        f += (wind * 0.05) * (facing[:, None] * nrm)\\n        f += (wind * 0.01) * wind_dir  # small constant push so a flat sheet still moves\\n        return f\\n\\n    # ----------------------------------------------------------------- step\\n    def step(self, stiffness, damping, wind, gravity=9.8,\\n             wind_dir=(0.0, 0.0, 1.0), dt=0.004, substeps=5):\\n        \\"\\"\\"Advance one *frame* (= `substeps` physics sub-steps of size dt).\\"\\"\\"\\n        wind_dir = np.asarray(wind_dir, dtype=np.float64)\\n        wind_dir = wind_dir / np.linalg.norm(wind_dir)\\n        for _ in range(substeps):\\n            f = self._forces(stiffness, wind, gravity, wind_dir)\\n            f -= damping * 0.5 * self.vel          # viscous damping\\n            self.vel += dt * f / self.mass\\n            self.vel[self.pinned] = 0.0\\n            self.pos += dt * self.vel\\n        return self.pos\\n\\n    @property\\n    def state(self):\\n        return self.pos.copy(), self.vel.copy()\\n", "simulation/generate_dataset.py": "\\"\\"\\"\\nGenerate a cloth trajectory dataset by running many randomised simulations.\\n\\nEach simulation samples (wind, stiffness, damping, [gravity]) and records\\n`frames` consecutive frames of positions and velocities.\\n\\nSaved as compressed .npz, split BY SIMULATION into train/val/test so that\\nframes of the same trajectory never appear in both train and test.\\n\\nUsage:\\n    python -m simulation.generate_dataset --sims 2000 --frames 30\\n\\"\\"\\"\\nimport argparse, os, time\\nimport numpy as np\\nfrom simulation.cloth import Cloth\\n\\nRANGES = {                      # sampling ranges for physical parameters\\n    \\"wind\\":      (0.0, 10.0),\\n    \\"stiffness\\": (0.1, 1.0),\\n    \\"damping\\":   (0.01, 0.5),\\n    \\"gravity\\":   (9.8, 9.8),    # fixed by default; widen to vary it\\n}\\n\\n\\ndef run_simulation(cloth, params, frames):\\n    cloth.reset()\\n    pos = np.empty((frames + 1, cloth.num_vertices, 3), dtype=np.float32)\\n    vel = np.empty_like(pos)\\n    pos[0], vel[0] = cloth.state\\n    for t in range(frames):\\n        cloth.step(params[\\"stiffness\\"], params[\\"damping\\"],\\n                   params[\\"wind\\"], params[\\"gravity\\"])\\n        pos[t + 1], vel[t + 1] = cloth.state\\n    return pos, vel\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\\"--sims\\", type=int, default=2000)\\n    ap.add_argument(\\"--frames\\", type=int, default=30)\\n    ap.add_argument(\\"--grid\\", type=int, default=10)\\n    ap.add_argument(\\"--seed\\", type=int, default=42)\\n    ap.add_argument(\\"--out\\", default=\\"data\\")\\n    args = ap.parse_args()\\n\\n    rng = np.random.default_rng(args.seed)\\n    cloth = Cloth(n=args.grid)\\n    os.makedirs(args.out, exist_ok=True)\\n\\n    P, V, PARAMS = [], [], []\\n    t0 = time.perf_counter()\\n    for s in range(args.sims):\\n        p = {k: rng.uniform(*r) for k, r in RANGES.items()}\\n        pos, vel = run_simulation(cloth, p, args.frames)\\n        if not np.isfinite(pos).all():          # discard unstable runs\\n            continue\\n        P.append(pos); V.append(vel)\\n        PARAMS.append([p[\\"wind\\"], p[\\"stiffness\\"], p[\\"damping\\"], p[\\"gravity\\"]])\\n        if (s + 1) % 200 == 0:\\n            print(f\\"  {s + 1}/{args.sims} simulations\\")\\n    total = time.perf_counter() - t0\\n\\n    P, V, PARAMS = np.stack(P), np.stack(V), np.array(PARAMS, dtype=np.float32)\\n    n_sims = len(P)\\n    ms_per_frame = 1000 * total / (n_sims * args.frames)\\n\\n    # Split by simulation: 80 / 10 / 10\\n    order = rng.permutation(n_sims)\\n    a, b = int(0.8 * n_sims), int(0.9 * n_sims)\\n    for name, ids in [(\\"train\\", order[:a]), (\\"val\\", order[a:b]), (\\"test\\", order[b:])]:\\n        np.savez_compressed(\\n            os.path.join(args.out, f\\"{name}.npz\\"),\\n            positions=P[ids], velocities=V[ids], params=PARAMS[ids],\\n            param_names=np.array([\\"wind\\", \\"stiffness\\", \\"damping\\", \\"gravity\\"]),\\n        )\\n        print(f\\"{name:5s}: {len(ids)} simulations\\")\\n\\n    print(f\\"\\\\nKept {n_sims}/{args.sims} simulations ({args.frames} frames each)\\")\\n    print(f\\"Physics cost (measured): {ms_per_frame:.2f} ms/frame on this machine\\")\\n    np.save(os.path.join(args.out, \\"physics_ms_per_frame.npy\\"), ms_per_frame)\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n", "model/__init__.py": "", "model/model.py": "import torch.nn as nn\\n\\n\\nclass ClothMLP(nn.Module):\\n    \\"\\"\\"Fully connected network: (cloth state + physics params) -> change in state.\\"\\"\\"\\n\\n    def __init__(self, input_dim, output_dim, hidden=(256, 512, 512)):\\n        super().__init__()\\n        layers, d = [], input_dim\\n        for h in hidden:\\n            layers += [nn.Linear(d, h), nn.ReLU()]\\n            d = h\\n        layers.append(nn.Linear(d, output_dim))\\n        self.net = nn.Sequential(*layers)\\n\\n    def forward(self, x):\\n        return self.net(x)\\n", "model/train.py": "\\"\\"\\"\\nTrain an MLP to predict the NEXT cloth frame (Approach B).\\n\\n    input  = [ position - rest (V*3) | velocity (V*3) | wind, stiffness, damping, gravity ]\\n    output = [ delta position (V*3)  | delta velocity (V*3) ]\\n\\nUsage (from project root):\\n    python -m model.train --epochs 100\\n\\"\\"\\"\\nimport argparse, json, os, time\\nimport numpy as np\\nimport torch\\nimport torch.nn as nn\\nfrom model.model import ClothMLP\\nfrom model.predict import ClothPredictor\\n\\n\\ndef load(data_dir, split):\\n    d = np.load(os.path.join(data_dir, f\\"{split}.npz\\"))\\n    return d[\\"positions\\"], d[\\"velocities\\"], d[\\"params\\"]\\n\\n\\ndef make_pairs(P, V, PR, rest):\\n    \\"\\"\\"Turn trajectories into (state_t -> change to state_t+1) training pairs.\\"\\"\\"\\n    S, T1 = P.shape[:2]\\n    T = T1 - 1\\n    disp = (P[:, :-1] - rest).reshape(S, T, -1)\\n    vel = V[:, :-1].reshape(S, T, -1)\\n    prm = np.repeat(PR[:, None, :], T, axis=1)\\n    X = np.concatenate([disp, vel, prm], -1).reshape(S * T, -1)\\n    dP = (P[:, 1:] - P[:, :-1]).reshape(S, T, -1)\\n    dV = (V[:, 1:] - V[:, :-1]).reshape(S, T, -1)\\n    Y = np.concatenate([dP, dV], -1).reshape(S * T, -1)\\n    return X.astype(np.float32), Y.astype(np.float32)\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\\"--data\\", default=\\"data\\")\\n    ap.add_argument(\\"--out\\", default=\\"model/cloth_mlp.pt\\")\\n    ap.add_argument(\\"--results\\", default=\\"results\\")\\n    ap.add_argument(\\"--epochs\\", type=int, default=100)\\n    ap.add_argument(\\"--batch\\", type=int, default=256)\\n    ap.add_argument(\\"--lr\\", type=float, default=1e-3)\\n    ap.add_argument(\\"--hidden\\", type=int, nargs=\\"+\\", default=[256, 512, 512])\\n    ap.add_argument(\\"--noise\\", type=float, default=0.0,\\n                    help=\\"Gaussian noise added to normalised inputs (helps long rollouts)\\")\\n    ap.add_argument(\\"--seed\\", type=int, default=0)\\n    args = ap.parse_args()\\n\\n    torch.manual_seed(args.seed); np.random.seed(args.seed)\\n    device = \\"cuda\\" if torch.cuda.is_available() else \\"cpu\\"\\n    os.makedirs(args.results, exist_ok=True)\\n\\n    Ptr, Vtr, PRtr = load(args.data, \\"train\\")\\n    Pva, Vva, PRva = load(args.data, \\"val\\")\\n    Pte, Vte, PRte = load(args.data, \\"test\\")\\n\\n    rest = Ptr[0, 0]                                            # frame 0 = rest pose\\n    moved = np.abs(Ptr - Ptr[:, :1]).max(axis=(0, 1, 3))        # per-vertex max movement\\n    pinned = moved < 1e-9\\n\\n    Xtr, Ytr = make_pairs(Ptr, Vtr, PRtr, rest)\\n    Xva, Yva = make_pairs(Pva, Vva, PRva, rest)\\n    Xte, Yte = make_pairs(Pte, Vte, PRte, rest)\\n    print(f\\"pairs  train {len(Xtr)}  val {len(Xva)}  test {len(Xte)}   input {Xtr.shape[1]}  output {Ytr.shape[1]}\\")\\n\\n    # Normalisation statistics come from the TRAIN set only\\n    x_mean, x_std = Xtr.mean(0), np.maximum(Xtr.std(0), 1e-6)\\n    y_mean, y_std = Ytr.mean(0), np.maximum(Ytr.std(0), 1e-6)\\n    nx = lambda X: torch.tensor((X - x_mean) / x_std, device=device)\\n    ny = lambda Y: torch.tensor((Y - y_mean) / y_std, device=device)\\n    Xtr_t, Ytr_t, Xva_t, Yva_t = nx(Xtr), ny(Ytr), nx(Xva), ny(Yva)\\n\\n    model = ClothMLP(Xtr.shape[1], Ytr.shape[1], tuple(args.hidden)).to(device)\\n    opt = torch.optim.AdamW(model.parameters(), lr=args.lr, weight_decay=1e-5)\\n    sched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=args.epochs)\\n    criterion = nn.MSELoss()\\n\\n    best, history = float(\\"inf\\"), {\\"train\\": [], \\"val\\": []}\\n    t0 = time.time()\\n    for epoch in range(1, args.epochs + 1):\\n        model.train()\\n        perm = torch.randperm(len(Xtr_t), device=device)\\n        run = 0.0\\n        for i in range(0, len(perm), args.batch):\\n            idx = perm[i:i + args.batch]\\n            xb, yb = Xtr_t[idx], Ytr_t[idx]\\n            if args.noise > 0:\\n                xb = xb + args.noise * torch.randn_like(xb)\\n            loss = criterion(model(xb), yb)\\n            opt.zero_grad(); loss.backward(); opt.step()\\n            run += loss.item() * len(idx)\\n        sched.step()\\n\\n        model.eval()\\n        with torch.no_grad():\\n            val = criterion(model(Xva_t), Yva_t).item()\\n        history[\\"train\\"].append(run / len(perm)); history[\\"val\\"].append(val)\\n\\n        if val < best:\\n            best = val\\n            torch.save({\\n                \\"state_dict\\": model.state_dict(), \\"input_dim\\": Xtr.shape[1],\\n                \\"output_dim\\": Ytr.shape[1], \\"hidden\\": list(args.hidden),\\n                \\"x_mean\\": x_mean, \\"x_std\\": x_std, \\"y_mean\\": y_mean, \\"y_std\\": y_std,\\n                \\"rest_pos\\": rest, \\"pinned\\": pinned,\\n            }, args.out)\\n        if epoch % 5 == 0 or epoch == 1:\\n            print(f\\"epoch {epoch:3d}/{args.epochs}  train {history[\'train\'][-1]:.5f}  val {val:.5f}\\")\\n    print(f\\"training time {time.time() - t0:.1f}s   best val loss {best:.5f}\\")\\n\\n    # ------------------------------------------------------------ evaluation\\n    predictor = ClothPredictor(args.out, device=\\"cpu\\")\\n    results = {\\"best_val_loss_normalised\\": best}\\n\\n    # (1) one-step error: predict frame t+1 from the TRUE frame t\\n    S, T1 = Pte.shape[:2]; T = T1 - 1\\n    pos_t = Pte[:, :-1].reshape(S * T, -1, 3)\\n    vel_t = Vte[:, :-1].reshape(S * T, -1, 3)\\n    prm = np.repeat(PRte[:, None, :], T, axis=1).reshape(S * T, -1)\\n    pred_pos, _ = predictor.step(pos_t, vel_t, prm)\\n    true_pos = Pte[:, 1:].reshape(S * T, -1, 3)\\n    results[\\"one_step_MSE\\"] = float(np.mean((pred_pos - true_pos) ** 2))\\n    results[\\"one_step_MAE\\"] = float(np.mean(np.abs(pred_pos - true_pos)))\\n\\n    # (2) rollout error: start at rest, feed predictions back in for T frames\\n    roll = predictor.rollout(PRte, T)\\n    err = roll - Pte\\n    results[\\"rollout_MSE\\"] = float(np.mean(err ** 2))\\n    results[\\"rollout_MAE\\"] = float(np.mean(np.abs(err)))\\n    per_frame = np.linalg.norm(err, axis=-1).mean(axis=(0, 2))            # metres, per frame\\n    baseline = np.linalg.norm(Pte - rest, axis=-1).mean(axis=(0, 2))      # \\"cloth never moves\\"\\n    results[\\"rollout_mean_vertex_error_per_frame_m\\"] = per_frame.tolist()\\n    results[\\"baseline_rest_pose_error_per_frame_m\\"] = baseline.tolist()\\n    results[\\"rollout_final_frame_error_m\\"] = float(per_frame[-1])\\n\\n    # (3) wind breakdown (Experiment 1 from the plan)\\n    wind = PRte[:, 0]\\n    bins = [0, 2, 4, 6, 8, 10.01]\\n    by_wind = {}\\n    for lo, hi in zip(bins[:-1], bins[1:]):\\n        m = (wind >= lo) & (wind < hi)\\n        if m.any():\\n            by_wind[f\\"{lo}-{min(hi, 10)}\\"] = float(np.linalg.norm(err[m], axis=-1).mean())\\n    results[\\"rollout_error_by_wind_m\\"] = by_wind\\n\\n    # (4) timing: one frame, batch size 1\\n    p0 = np.repeat(predictor.rest[None], 1, 0); v0 = np.zeros_like(p0); q0 = PRte[:1]\\n    for _ in range(20): predictor.step(p0, v0, q0)                        # warm-up\\n    t = time.perf_counter()\\n    for _ in range(300): predictor.step(p0, v0, q0)\\n    results[\\"mlp_ms_per_frame\\"] = 1000 * (time.perf_counter() - t) / 300\\n    phys = os.path.join(args.data, \\"physics_ms_per_frame.npy\\")\\n    if os.path.exists(phys):\\n        results[\\"physics_ms_per_frame\\"] = float(np.load(phys))\\n        results[\\"speedup\\"] = results[\\"physics_ms_per_frame\\"] / results[\\"mlp_ms_per_frame\\"]\\n\\n    with open(os.path.join(args.results, \\"metrics.json\\"), \\"w\\") as f:\\n        json.dump(results, f, indent=2)\\n    print(\\"\\\\n\\" + json.dumps({k: v for k, v in results.items() if not isinstance(v, (list, dict))}, indent=2))\\n    print(\\"error by wind:\\", results[\\"rollout_error_by_wind_m\\"])\\n\\n    try:\\n        import matplotlib; matplotlib.use(\\"Agg\\")\\n        import matplotlib.pyplot as plt\\n        fig, ax = plt.subplots(1, 2, figsize=(11, 4))\\n        ax[0].plot(history[\\"train\\"], label=\\"train\\"); ax[0].plot(history[\\"val\\"], label=\\"val\\")\\n        ax[0].set_yscale(\\"log\\"); ax[0].set_xlabel(\\"epoch\\"); ax[0].set_ylabel(\\"MSE (normalised)\\")\\n        ax[0].set_title(\\"Training curve\\"); ax[0].legend()\\n        ax[1].plot(per_frame, label=\\"MLP rollout\\"); ax[1].plot(baseline, \\"--\\", label=\\"cloth stays at rest\\")\\n        ax[1].set_xlabel(\\"frame\\"); ax[1].set_ylabel(\\"mean vertex error (m)\\")\\n        ax[1].set_title(\\"Rollout error over time\\"); ax[1].legend()\\n        plt.tight_layout(); plt.savefig(os.path.join(args.results, \\"training_results.png\\"), dpi=150)\\n    except ImportError:\\n        print(\\"matplotlib not installed - skipped plots\\")\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n", "model/predict.py": "\\"\\"\\"Load a trained checkpoint and roll the cloth forward frame by frame.\\"\\"\\"\\nimport numpy as np\\nimport torch\\nfrom model.model import ClothMLP\\n\\n\\nclass ClothPredictor:\\n    def __init__(self, path=\\"model/cloth_mlp.pt\\", device=\\"cpu\\"):\\n        ck = torch.load(path, map_location=device, weights_only=False)\\n        self.device = device\\n        self.rest = ck[\\"rest_pos\\"].astype(np.float32)          # (V, 3)\\n        self.pinned = ck[\\"pinned\\"]                              # (V,) bool\\n        self.V = self.rest.shape[0]\\n        t = lambda a: torch.tensor(a, dtype=torch.float32, device=device)\\n        self.x_mean, self.x_std = t(ck[\\"x_mean\\"]), t(ck[\\"x_std\\"])\\n        self.y_mean, self.y_std = t(ck[\\"y_mean\\"]), t(ck[\\"y_std\\"])\\n        self.model = ClothMLP(ck[\\"input_dim\\"], ck[\\"output_dim\\"], tuple(ck[\\"hidden\\"])).to(device)\\n        self.model.load_state_dict(ck[\\"state_dict\\"])\\n        self.model.eval()\\n\\n    @torch.no_grad()\\n    def step(self, pos, vel, params):\\n        \\"\\"\\"pos, vel: (B, V, 3); params: (B, 4) [wind, stiffness, damping, gravity].\\"\\"\\"\\n        B, V3 = pos.shape[0], self.V * 3\\n        x = np.concatenate([(pos - self.rest).reshape(B, -1),\\n                            vel.reshape(B, -1), params], axis=1).astype(np.float32)\\n        x = (torch.from_numpy(x).to(self.device) - self.x_mean) / self.x_std\\n        y = (self.model(x) * self.y_std + self.y_mean).cpu().numpy()\\n        new_pos = pos + y[:, :V3].reshape(B, self.V, 3)\\n        new_vel = vel + y[:, V3:].reshape(B, self.V, 3)\\n        new_pos[:, self.pinned] = self.rest[self.pinned]        # pinned vertices never move\\n        new_vel[:, self.pinned] = 0.0\\n        return new_pos, new_vel\\n\\n    def rollout(self, params, frames):\\n        \\"\\"\\"Start from the rest pose and predict `frames` frames. Returns (B, frames+1, V, 3).\\"\\"\\"\\n        params = np.atleast_2d(np.asarray(params, dtype=np.float32))\\n        B = params.shape[0]\\n        pos = np.repeat(self.rest[None], B, axis=0)\\n        vel = np.zeros_like(pos)\\n        out = [pos.copy()]\\n        for _ in range(frames):\\n            pos, vel = self.step(pos, vel, params)\\n            out.append(pos.copy())\\n        return np.stack(out, axis=1)\\n", "visualization/__init__.py": "", "visualization/visualize.py": "\\"\\"\\"\\nPlotting + comparison helpers shared by the notebook, main.py and the Streamlit app.\\nNothing here imports torch, so the physics side can be plotted on its own.\\n\\"\\"\\"\\nimport time\\nimport numpy as np\\nimport matplotlib.pyplot as plt\\nfrom matplotlib import animation\\nfrom simulation.cloth import Cloth\\n\\nPHYS_COLOR, MLP_COLOR = \\"tab:blue\\", \\"tab:orange\\"\\n\\n\\n# ------------------------------------------------------------------ running\\ndef grid_size(num_vertices):\\n    n = int(round(num_vertices ** 0.5))\\n    assert n * n == num_vertices, \\"vertex count is not a square grid\\"\\n    return n\\n\\n\\ndef run_physics(wind, stiffness, damping, frames, gravity=9.8, grid=10):\\n    \\"\\"\\"Ground-truth simulation. Returns (frames+1, V, 3) and measured ms/frame.\\"\\"\\"\\n    cloth = Cloth(n=grid)\\n    traj = [cloth.pos.copy()]\\n    t0 = time.perf_counter()\\n    for _ in range(frames):\\n        cloth.step(stiffness, damping, wind, gravity)\\n        traj.append(cloth.pos.copy())\\n    ms = 1000 * (time.perf_counter() - t0) / frames\\n    return np.stack(traj).astype(np.float32), ms\\n\\n\\ndef run_mlp(predictor, wind, stiffness, damping, frames, gravity=9.8):\\n    \\"\\"\\"MLP rollout from the rest pose. Returns (frames+1, V, 3) and measured ms/frame.\\"\\"\\"\\n    params = np.array([[wind, stiffness, damping, gravity]], dtype=np.float32)\\n    predictor.rollout(params, 1)                       # warm-up (not timed)\\n    t0 = time.perf_counter()\\n    traj = predictor.rollout(params, frames)[0]\\n    ms = 1000 * (time.perf_counter() - t0) / frames\\n    return traj, ms\\n\\n\\ndef vertex_errors(phys, mlp):\\n    \\"\\"\\"Per-frame mean Euclidean vertex error (metres). Inputs: (T, V, 3).\\"\\"\\"\\n    return np.linalg.norm(phys - mlp, axis=-1).mean(axis=1)\\n\\n\\n# ------------------------------------------------------------------ drawing\\ndef _setup_axes(ax, rest, zlim=(-0.3, 1.0)):\\n    xr = (rest[:, 0].min() - 0.15, rest[:, 0].max() + 0.15)\\n    yr = (rest[:, 1].min() - 0.25, rest[:, 1].max() + 0.15)\\n    ax.set_xlim(*xr); ax.set_ylim(*zlim); ax.set_zlim(*yr)\\n    ax.set_box_aspect((xr[1] - xr[0], zlim[1] - zlim[0], yr[1] - yr[0]))\\n    ax.set_xlabel(\\"x\\"); ax.set_ylabel(\\"z (wind)\\"); ax.set_zlabel(\\"y\\")\\n    ax.set_xticklabels([]); ax.set_yticklabels([]); ax.set_zticklabels([])\\n    ax.view_init(elev=15, azim=-60)\\n\\n\\ndef draw_cloth(ax, pos, rest, color=PHYS_COLOR, label=None, clear=False):\\n    \\"\\"\\"Draw one cloth frame as a wireframe. Vertical axis is y, wind blows along +z.\\"\\"\\"\\n    if clear:\\n        ax.cla()\\n    n = grid_size(len(pos))\\n    g = pos.reshape(n, n, 3)\\n    for i in range(n):\\n        ax.plot(g[i, :, 0], g[i, :, 2], g[i, :, 1], color=color, lw=1.1,\\n                label=label if i == 0 else None)\\n        ax.plot(g[:, i, 0], g[:, i, 2], g[:, i, 1], color=color, lw=1.1)\\n    ax.plot(g[0, :, 0], g[0, :, 2], g[0, :, 1], color=\\"black\\", lw=3)   # pinned edge\\n    _setup_axes(ax, rest)\\n\\n\\ndef plot_trajectory(traj, rest, frames_to_show, color=PHYS_COLOR, title=\\"\\"):\\n    k = len(frames_to_show)\\n    fig = plt.figure(figsize=(3.2 * k, 3.6))\\n    for c, f in enumerate(frames_to_show):\\n        ax = fig.add_subplot(1, k, c + 1, projection=\\"3d\\")\\n        draw_cloth(ax, traj[f], rest, color)\\n        ax.set_title(f\\"frame {f}\\", fontsize=10)\\n    if title:\\n        fig.suptitle(title)\\n    fig.tight_layout()\\n    return fig\\n\\n\\ndef compare_frames(phys, mlp, rest, frames_to_show):\\n    \\"\\"\\"Rows: physics, MLP, overlay (blue = physics, orange = MLP). Columns: frames.\\"\\"\\"\\n    k = len(frames_to_show)\\n    fig = plt.figure(figsize=(3.2 * k, 9.6))\\n    rows = [(\\"Physics simulation\\", PHYS_COLOR), (\\"MLP prediction\\", MLP_COLOR), (\\"Overlay\\", None)]\\n    for r, (name, col) in enumerate(rows):\\n        for c, f in enumerate(frames_to_show):\\n            ax = fig.add_subplot(3, k, r * k + c + 1, projection=\\"3d\\")\\n            if col is not None:\\n                draw_cloth(ax, (phys if r == 0 else mlp)[f], rest, col)\\n            else:\\n                draw_cloth(ax, phys[f], rest, PHYS_COLOR)\\n                draw_cloth(ax, mlp[f], rest, MLP_COLOR)\\n            if r == 0:\\n                ax.set_title(f\\"frame {f}\\", fontsize=10)\\n            if c == 0:\\n                ax.text2D(-0.05, 0.5, name, transform=ax.transAxes, rotation=90,\\n                          va=\\"center\\", fontsize=10)\\n    fig.tight_layout()\\n    return fig\\n\\n\\ndef error_heatmap(phys_pos, mlp_pos, ax=None, title=\\"Per-vertex error (m)\\"):\\n    \\"\\"\\"2D map of |physics - MLP| for each vertex of one frame.\\"\\"\\"\\n    n = grid_size(len(phys_pos))\\n    err = np.linalg.norm(phys_pos - mlp_pos, axis=1).reshape(n, n)\\n    if ax is None:\\n        _, ax = plt.subplots(figsize=(4.5, 4))\\n    im = ax.imshow(err, cmap=\\"magma\\")\\n    ax.set_title(title); ax.set_xticks([]); ax.set_yticks([])\\n    plt.colorbar(im, ax=ax, fraction=0.046)\\n    return ax\\n\\n\\ndef animate_compare(phys, mlp, rest, path=\\"results/compare.gif\\", fps=15):\\n    \\"\\"\\"Side-by-side GIF: physics | MLP | overlay.\\"\\"\\"\\n    fig = plt.figure(figsize=(12, 4.2))\\n    axs = [fig.add_subplot(1, 3, i + 1, projection=\\"3d\\") for i in range(3)]\\n\\n    def update(f):\\n        draw_cloth(axs[0], phys[f], rest, PHYS_COLOR, clear=True); axs[0].set_title(\\"Physics\\")\\n        draw_cloth(axs[1], mlp[f], rest, MLP_COLOR, clear=True);   axs[1].set_title(\\"MLP\\")\\n        draw_cloth(axs[2], phys[f], rest, PHYS_COLOR, clear=True)\\n        draw_cloth(axs[2], mlp[f], rest, MLP_COLOR)\\n        axs[2].set_title(f\\"Overlay  (frame {f})\\")\\n\\n    anim = animation.FuncAnimation(fig, update, frames=len(phys), interval=1000 / fps)\\n    anim.save(path, writer=animation.PillowWriter(fps=fps))\\n    plt.close(fig)\\n    return path\\n\\n\\n# ------------------------------------------------------------------ metrics plots\\ndef plot_error_curves(metrics, ax=None):\\n    if ax is None:\\n        _, ax = plt.subplots(figsize=(6, 3.8))\\n    ax.plot(metrics[\\"rollout_mean_vertex_error_per_frame_m\\"], label=\\"MLP rollout\\")\\n    ax.plot(metrics[\\"baseline_rest_pose_error_per_frame_m\\"], \\"--\\", label=\\"cloth stays at rest\\")\\n    ax.set_xlabel(\\"frame\\"); ax.set_ylabel(\\"mean vertex error (m)\\")\\n    ax.set_title(\\"Rollout error over time\\"); ax.legend()\\n    return ax\\n\\n\\ndef plot_error_by_wind(metrics, ax=None):\\n    if ax is None:\\n        _, ax = plt.subplots(figsize=(6, 3.8))\\n    d = metrics[\\"rollout_error_by_wind_m\\"]\\n    ax.bar(list(d.keys()), list(d.values()), color=MLP_COLOR)\\n    ax.set_xlabel(\\"wind strength bin\\"); ax.set_ylabel(\\"mean vertex error (m)\\")\\n    ax.set_title(\\"Error vs. wind strength\\")\\n    return ax\\n", "visualization/app.py": "\\"\\"\\"\\nInteractive demo.   Run from the project root:   streamlit run visualization/app.py\\nSliders control the physics parameters; the physics simulator and the trained MLP\\nare both run and shown side by side with MEASURED timings.\\n\\"\\"\\"\\nimport json, os, sys\\n\\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\\nsys.path.insert(0, ROOT)\\nos.chdir(ROOT)\\n\\nimport matplotlib\\nmatplotlib.use(\\"Agg\\")\\nimport matplotlib.pyplot as plt\\nimport numpy as np\\nimport streamlit as st\\n\\nfrom model.predict import ClothPredictor\\nfrom visualization import visualize as viz\\n\\nCKPT = \\"model/cloth_mlp.pt\\"\\nst.set_page_config(page_title=\\"Data-Driven Cloth\\", layout=\\"wide\\")\\nst.title(\\"Data-Driven Cloth for Interactive Applications\\")\\nst.caption(\\"Physics mass-spring simulation vs. a neural network trained to imitate it.\\")\\n\\nif not os.path.exists(CKPT):\\n    st.error(\\"No trained model found. Run `python main.py all` (or `python -m model.train`) first.\\")\\n    st.stop()\\n\\n\\n@st.cache_resource\\ndef get_predictor():\\n    return ClothPredictor(CKPT)\\n\\n\\npredictor = get_predictor()\\ngrid = viz.grid_size(predictor.V)\\nrest = predictor.rest\\n\\ntrained_frames = 30\\nif os.path.exists(\\"results/metrics.json\\"):\\n    with open(\\"results/metrics.json\\") as f:\\n        trained_frames = len(json.load(f)[\\"rollout_mean_vertex_error_per_frame_m\\"]) - 1\\n\\n# ------------------------------------------------------------------ controls\\nst.sidebar.header(\\"Cloth parameters\\")\\nwind = st.sidebar.slider(\\"Wind\\", 0.0, 10.0, 5.0, 0.1)\\nstiffness = st.sidebar.slider(\\"Stiffness\\", 0.1, 1.0, 0.5, 0.05)\\ndamping = st.sidebar.slider(\\"Damping\\", 0.01, 0.5, 0.2, 0.01)\\nframes = st.sidebar.slider(\\"Simulated frames\\", 5, trained_frames, trained_frames)\\nst.sidebar.caption(f\\"Sliders cover the ranges used for training data. \\"\\n                   f\\"The model was trained on {trained_frames}-frame trajectories.\\")\\n\\nphys, phys_ms = viz.run_physics(wind, stiffness, damping, frames, grid=grid)\\nmlp, mlp_ms = viz.run_mlp(predictor, wind, stiffness, damping, frames)\\nerr = viz.vertex_errors(phys, mlp)\\n\\nframe = st.slider(\\"Frame to display\\", 0, frames, frames)\\n\\n# ------------------------------------------------------------------ display\\nfig = plt.figure(figsize=(14, 4.6))\\ntitles = [\\"Physics simulation\\", \\"MLP prediction\\", \\"Overlay (blue = physics, orange = MLP)\\"]\\nfor i in range(3):\\n    ax = fig.add_subplot(1, 3, i + 1, projection=\\"3d\\")\\n    if i == 0:\\n        viz.draw_cloth(ax, phys[frame], rest, viz.PHYS_COLOR)\\n    elif i == 1:\\n        viz.draw_cloth(ax, mlp[frame], rest, viz.MLP_COLOR)\\n    else:\\n        viz.draw_cloth(ax, phys[frame], rest, viz.PHYS_COLOR)\\n        viz.draw_cloth(ax, mlp[frame], rest, viz.MLP_COLOR)\\n    ax.set_title(titles[i], fontsize=10)\\nst.pyplot(fig)\\nplt.close(fig)\\n\\nc1, c2, c3, c4 = st.columns(4)\\nc1.metric(\\"Physics (measured)\\", f\\"{phys_ms:.2f} ms/frame\\")\\nc2.metric(\\"MLP (measured)\\", f\\"{mlp_ms:.2f} ms/frame\\")\\nc3.metric(\\"Speed ratio (physics / MLP)\\", f\\"{phys_ms / mlp_ms:.2f}x\\")\\nc4.metric(f\\"Mean vertex error @ frame {frame}\\", f\\"{err[frame] * 100:.2f} cm\\")\\n\\nleft, right = st.columns(2)\\nwith left:\\n    st.subheader(\\"Error over time\\")\\n    st.line_chart({\\"mean vertex error (m)\\": err})\\nwith right:\\n    st.subheader(\\"Per-vertex error at this frame\\")\\n    f2, ax2 = plt.subplots(figsize=(4.5, 3.8))\\n    viz.error_heatmap(phys[frame], mlp[frame], ax=ax2, title=\\"\\")\\n    st.pyplot(f2)\\n    plt.close(f2)\\nst.caption(\\"Timings are measured live on this machine and include Python overhead. \\"\\n           \\"For a fair speed comparison use the larger-grid experiment in the README.\\")\\n", "notebooks/visualization.ipynb": "{\\n \\"cells\\": [\\n  {\\n   \\"cell_type\\": \\"markdown\\",\\n   \\"metadata\\": {},\\n   \\"source\\": [\\n    \\"# Data-Driven Cloth \\\\u2014 Visualization & Analysis\\\\n\\",\\n    \\"\\\\n\\",\\n    \\"This notebook explores the dataset, the physics simulator and the trained MLP.\\\\n\\",\\n    \\"Run it **after** `python main.py generate` and `python main.py train` so that\\\\n\\",\\n    \\"`data/*.npz`, `model/cloth_mlp.pt` and `results/metrics.json` exist.\\\\n\\",\\n    \\"\\\\n\\",\\n    \\"Axes in all 3D plots: `x` horizontal, `y` vertical (up), `z` = wind direction. The thick black line is the pinned top edge.\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"code\\",\\n   \\"metadata\\": {},\\n   \\"execution_count\\": null,\\n   \\"outputs\\": [],\\n   \\"source\\": [\\n    \\"import os, sys, json\\\\n\\",\\n    \\"ROOT = os.path.abspath(\\\\\\"..\\\\\\") if os.path.basename(os.getcwd()) == \\\\\\"notebooks\\\\\\" else os.getcwd()\\\\n\\",\\n    \\"os.chdir(ROOT); sys.path.insert(0, ROOT)\\\\n\\",\\n    \\"\\\\n\\",\\n    \\"import numpy as np\\\\n\\",\\n    \\"import matplotlib.pyplot as plt\\\\n\\",\\n    \\"%matplotlib inline\\\\n\\",\\n    \\"\\\\n\\",\\n    \\"from visualization import visualize as viz\\\\n\\",\\n    \\"from model.predict import ClothPredictor\\\\n\\",\\n    \\"\\\\n\\",\\n    \\"predictor = ClothPredictor(\\\\\\"model/cloth_mlp.pt\\\\\\")\\\\n\\",\\n    \\"rest = predictor.rest\\\\n\\",\\n    \\"metrics = json.load(open(\\\\\\"results/metrics.json\\\\\\"))\\\\n\\",\\n    \\"test = np.load(\\\\\\"data/test.npz\\\\\\")\\\\n\\",\\n    \\"print(\\\\\\"Loaded model for a\\\\\\", viz.grid_size(predictor.V), \\\\\\"x\\\\\\", viz.grid_size(predictor.V), \\\\\\"cloth\\\\\\")\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"markdown\\",\\n   \\"metadata\\": {},\\n   \\"source\\": [\\n    \\"## 1. The dataset\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"code\\",\\n   \\"metadata\\": {},\\n   \\"execution_count\\": null,\\n   \\"outputs\\": [],\\n   \\"source\\": [\\n    \\"for split in [\\\\\\"train\\\\\\", \\\\\\"val\\\\\\", \\\\\\"test\\\\\\"]:\\\\n\\",\\n    \\"    d = np.load(f\\\\\\"data/{split}.npz\\\\\\")\\\\n\\",\\n    \\"    print(f\\\\\\"{split:5s} positions {d[\'positions\'].shape}  velocities {d[\'velocities\'].shape}  params {d[\'params\'].shape}\\\\\\")\\\\n\\",\\n    \\"\\\\n\\",\\n    \\"params = np.concatenate([np.load(f\\\\\\"data/{s}.npz\\\\\\")[\\\\\\"params\\\\\\"] for s in [\\\\\\"train\\\\\\", \\\\\\"val\\\\\\", \\\\\\"test\\\\\\"]])\\\\n\\",\\n    \\"fig, ax = plt.subplots(1, 3, figsize=(12, 3))\\\\n\\",\\n    \\"for i, name in enumerate([\\\\\\"wind\\\\\\", \\\\\\"stiffness\\\\\\", \\\\\\"damping\\\\\\"]):\\\\n\\",\\n    \\"    ax[i].hist(params[:, i], bins=30, color=\\\\\\"tab:blue\\\\\\"); ax[i].set_title(name)\\\\n\\",\\n    \\"fig.suptitle(\\\\\\"Sampled physics parameters (all splits)\\\\\\"); fig.tight_layout(); plt.show()\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"markdown\\",\\n   \\"metadata\\": {},\\n   \\"source\\": [\\n    \\"## 2. One physics trajectory\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"code\\",\\n   \\"metadata\\": {},\\n   \\"execution_count\\": null,\\n   \\"outputs\\": [],\\n   \\"source\\": [\\n    \\"phys, ms = viz.run_physics(wind=6.0, stiffness=0.5, damping=0.2, frames=30)\\\\n\\",\\n    \\"viz.plot_trajectory(phys, rest, [0, 5, 10, 20, 30], title=\\\\\\"Physics simulation, wind = 6\\\\\\")\\\\n\\",\\n    \\"plt.show()\\\\n\\",\\n    \\"print(f\\\\\\"Physics cost: {ms:.2f} ms/frame (measured here)\\\\\\")\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"markdown\\",\\n   \\"metadata\\": {},\\n   \\"source\\": [\\n    \\"## 3. Effect of wind (physics simulator, final frame)\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"code\\",\\n   \\"metadata\\": {},\\n   \\"execution_count\\": null,\\n   \\"outputs\\": [],\\n   \\"source\\": [\\n    \\"winds = [0, 2.5, 5, 7.5, 10]\\\\n\\",\\n    \\"fig = plt.figure(figsize=(3.2 * len(winds), 3.6))\\\\n\\",\\n    \\"for i, w in enumerate(winds):\\\\n\\",\\n    \\"    traj, _ = viz.run_physics(w, 0.5, 0.2, 30)\\\\n\\",\\n    \\"    ax = fig.add_subplot(1, len(winds), i + 1, projection=\\\\\\"3d\\\\\\")\\\\n\\",\\n    \\"    viz.draw_cloth(ax, traj[-1], rest); ax.set_title(f\\\\\\"wind = {w}\\\\\\")\\\\n\\",\\n    \\"fig.tight_layout(); plt.show()\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"markdown\\",\\n   \\"metadata\\": {},\\n   \\"source\\": [\\n    \\"## 4. Physics vs. MLP on an unseen test simulation\\\\n\\",\\n    \\"\\\\n\\",\\n    \\"The test split was never used for training or model selection, so this is an honest check.\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"code\\",\\n   \\"metadata\\": {},\\n   \\"execution_count\\": null,\\n   \\"outputs\\": [],\\n   \\"source\\": [\\n    \\"i = 0                                    # try other indices: 0 .. len(test[\'params\'])-1\\\\n\\",\\n    \\"wind, stiff, damp, grav = test[\\\\\\"params\\\\\\"][i]\\\\n\\",\\n    \\"gt = test[\\\\\\"positions\\\\\\"][i]                # ground-truth physics trajectory\\\\n\\",\\n    \\"frames = len(gt) - 1\\\\n\\",\\n    \\"pred = predictor.rollout(test[\\\\\\"params\\\\\\"][i], frames)[0]\\\\n\\",\\n    \\"print(f\\\\\\"test sim {i}: wind={wind:.2f}  stiffness={stiff:.2f}  damping={damp:.2f}\\\\\\")\\\\n\\",\\n    \\"\\\\n\\",\\n    \\"viz.compare_frames(gt, pred, rest, [0, frames // 3, 2 * frames // 3, frames])\\\\n\\",\\n    \\"plt.show()\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"markdown\\",\\n   \\"metadata\\": {},\\n   \\"source\\": [\\n    \\"## 5. Where is the error? (per-vertex, final frame)\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"code\\",\\n   \\"metadata\\": {},\\n   \\"execution_count\\": null,\\n   \\"outputs\\": [],\\n   \\"source\\": [\\n    \\"fig, ax = plt.subplots(1, 2, figsize=(9, 3.8))\\\\n\\",\\n    \\"viz.error_heatmap(gt[-1], pred[-1], ax=ax[0], title=\\\\\\"Final frame error (m)\\\\\\")\\\\n\\",\\n    \\"viz.error_heatmap(gt[frames // 2], pred[frames // 2], ax=ax[1], title=\\\\\\"Mid-trajectory error (m)\\\\\\")\\\\n\\",\\n    \\"fig.tight_layout(); plt.show()\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"markdown\\",\\n   \\"metadata\\": {},\\n   \\"source\\": [\\n    \\"## 6. Test-set metrics\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"code\\",\\n   \\"metadata\\": {},\\n   \\"execution_count\\": null,\\n   \\"outputs\\": [],\\n   \\"source\\": [\\n    \\"print(\\\\\\"one-step  MSE: %.3e   MAE: %.3e\\\\\\" % (metrics[\\\\\\"one_step_MSE\\\\\\"], metrics[\\\\\\"one_step_MAE\\\\\\"]))\\\\n\\",\\n    \\"print(\\\\\\"rollout   MSE: %.3e   MAE: %.3e\\\\\\" % (metrics[\\\\\\"rollout_MSE\\\\\\"], metrics[\\\\\\"rollout_MAE\\\\\\"]))\\\\n\\",\\n    \\"print(\\\\\\"final-frame mean vertex error: %.2f cm\\\\\\" % (100 * metrics[\\\\\\"rollout_final_frame_error_m\\\\\\"]))\\\\n\\",\\n    \\"\\\\n\\",\\n    \\"fig, ax = plt.subplots(1, 2, figsize=(12, 3.8))\\\\n\\",\\n    \\"viz.plot_error_curves(metrics, ax=ax[0])\\\\n\\",\\n    \\"viz.plot_error_by_wind(metrics, ax=ax[1])\\\\n\\",\\n    \\"fig.tight_layout(); plt.show()\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"markdown\\",\\n   \\"metadata\\": {},\\n   \\"source\\": [\\n    \\"## 7. Speed: physics vs. MLP\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"code\\",\\n   \\"metadata\\": {},\\n   \\"execution_count\\": null,\\n   \\"outputs\\": [],\\n   \\"source\\": [\\n    \\"import pandas as pd\\\\n\\",\\n    \\"rows = {\\\\\\"Physics (NumPy mass-spring)\\\\\\": metrics.get(\\\\\\"physics_ms_per_frame\\\\\\"),\\\\n\\",\\n    \\"        \\\\\\"MLP (batch size 1, CPU)\\\\\\": metrics[\\\\\\"mlp_ms_per_frame\\\\\\"]}\\\\n\\",\\n    \\"print(pd.Series(rows, name=\\\\\\"ms / frame\\\\\\").to_frame().round(3))\\\\n\\",\\n    \\"if \\\\\\"speedup\\\\\\" in metrics:\\\\n\\",\\n    \\"    print(f\\\\\\"\\\\\\\\nMeasured ratio physics / MLP: {metrics[\'speedup\']:.2f}x\\\\\\")\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"markdown\\",\\n   \\"metadata\\": {},\\n   \\"source\\": [\\n    \\"## 8. Interactive explorer\\\\n\\",\\n    \\"\\\\n\\",\\n    \\"Drag the sliders to compare physics and MLP for any parameter combination (requires `ipywidgets`).\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"code\\",\\n   \\"metadata\\": {},\\n   \\"execution_count\\": null,\\n   \\"outputs\\": [],\\n   \\"source\\": [\\n    \\"from ipywidgets import interact, FloatSlider, IntSlider\\\\n\\",\\n    \\"\\\\n\\",\\n    \\"@interact(wind=FloatSlider(5, min=0, max=10, step=0.5),\\\\n\\",\\n    \\"          stiffness=FloatSlider(0.5, min=0.1, max=1.0, step=0.05),\\\\n\\",\\n    \\"          damping=FloatSlider(0.2, min=0.01, max=0.5, step=0.01),\\\\n\\",\\n    \\"          frame=IntSlider(30, min=0, max=30))\\\\n\\",\\n    \\"def explore(wind, stiffness, damping, frame):\\\\n\\",\\n    \\"    p, p_ms = viz.run_physics(wind, stiffness, damping, 30)\\\\n\\",\\n    \\"    m, m_ms = viz.run_mlp(predictor, wind, stiffness, damping, 30)\\\\n\\",\\n    \\"    fig = viz.compare_frames(p, m, rest, [frame])\\\\n\\",\\n    \\"    fig.suptitle(f\\\\\\"frame {frame}  |  mean vertex error {100 * viz.vertex_errors(p, m)[frame]:.2f} cm  |  \\\\\\"\\\\n\\",\\n    \\"                 f\\\\\\"physics {p_ms:.2f} ms/frame, MLP {m_ms:.2f} ms/frame\\\\\\")\\\\n\\",\\n    \\"    plt.show()\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"markdown\\",\\n   \\"metadata\\": {},\\n   \\"source\\": [\\n    \\"## 9. Save an animation for the presentation\\"\\n   ]\\n  },\\n  {\\n   \\"cell_type\\": \\"code\\",\\n   \\"metadata\\": {},\\n   \\"execution_count\\": null,\\n   \\"outputs\\": [],\\n   \\"source\\": [\\n    \\"from IPython.display import Image\\\\n\\",\\n    \\"p, _ = viz.run_physics(6.0, 0.5, 0.2, 30)\\\\n\\",\\n    \\"m, _ = viz.run_mlp(predictor, 6.0, 0.5, 0.2, 30)\\\\n\\",\\n    \\"os.makedirs(\\\\\\"results\\\\\\", exist_ok=True)\\\\n\\",\\n    \\"viz.animate_compare(p, m, rest, \\\\\\"results/compare.gif\\\\\\")\\\\n\\",\\n    \\"Image(filename=\\\\\\"results/compare.gif\\\\\\")\\"\\n   ]\\n  }\\n ],\\n \\"metadata\\": {\\n  \\"kernelspec\\": {\\n   \\"display_name\\": \\"Python 3\\",\\n   \\"language\\": \\"python\\",\\n   \\"name\\": \\"python3\\"\\n  },\\n  \\"language_info\\": {\\n   \\"name\\": \\"python\\"\\n  }\\n },\\n \\"nbformat\\": 4,\\n \\"nbformat_minor\\": 5\\n}"}')

